// API client. LIVE mode talks to the Node gateway (/api). If the gateway is unreachable (e.g. the hosted static
// preview), DEMO mode replays responses recorded from the real Python pipeline (public/demo/*.json, generated by
// web/scripts/make_fixtures.py). The UI always shows which mode it is in.
export const slug = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 80);

let MODE = null; // "live" | "demo"
const demoCache = {};
async function demo(name) {
  if (!demoCache[name]) {
    const r = await fetch(`./demo/${name}.json`);
    if (!r.ok) throw new Error(`No recorded demo response for "${name}". Run the Node server for live answers.`);
    demoCache[name] = await r.json();
  }
  return demoCache[name];
}

export async function detectMode() {
  if (MODE) return MODE;
  try {
    const r = await fetch("/api/health", { signal: AbortSignal.timeout(2500) });
    MODE = r.ok ? "live" : "demo";
  } catch { MODE = "demo"; }
  return MODE;
}
export const getMode = () => MODE;

async function get(path, demoName) {
  if ((await detectMode()) === "demo") return demo(demoName);
  const r = await fetch(`/api/${path}`);
  if (!r.ok) throw new Error((await r.json().catch(() => ({}))).error || r.statusText);
  return r.json();
}
export const api = {
  kb: () => get("kb", "kb"),
  instruments: () => get("instruments", "instruments"),
  metrics: () => get("metrics", "metrics"),
  reports: () => get("reports", "reports"),
  config: () => get("config", "config"),
  resources: () => demo("resources"), // static directory snapshot (same YAML the navigator uses)

  async retrieve(body) {
    if ((await detectMode()) === "demo") {
      const all = await demo("retrieve");
      const q = all[slug(body.query)];
      if (!q) throw new Error("Demo mode has recorded results only for the preset queries. Run the Node server to try your own.");
      const key = `${body.top_k}|${body.rerank}|${body.mmr_lambda}`; // topic filter needs the live server
      return q[key] || q[Object.keys(q)[0]];
    }
    const r = await fetch("/api/retrieve", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
    if (!r.ok) throw new Error((await r.json()).error);
    return r.json();
  },

  // Streams agent steps. onStep(step) is called per node; resolves with the final result.
  async chat({ text, workflow = "dynamic", sessionId, image, use_rag = true, history = [] }, onStep) {
    if ((await detectMode()) === "demo") {
      const key = slug([...history, text, image?.name || ""].filter(Boolean).join(" >> ") + (use_rag ? "" : " norag") + (workflow === "static" ? " static" : ""));
      const rec = await demo(`chat/${key}`);
      for (const s of rec.steps) { await new Promise((r) => setTimeout(r, 140)); onStep?.(s); }
      return { ...rec.result, sessionId: "demo" };
    }
    const res = await fetch("/api/chat", {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ text, workflow, sessionId, use_rag, image_b64: image?.dataUrl, image_name: image?.name }),
    });
    if (!res.ok || !res.body) throw new Error((await res.json().catch(() => ({}))).error || "Request failed");
    const reader = res.body.getReader();
    const dec = new TextDecoder();
    let buf = "", result = null, sid = sessionId;
    for (;;) {
      const { value, done } = await reader.read();
      if (done) break;
      buf += dec.decode(value, { stream: true });
      let i;
      while ((i = buf.indexOf("\n\n")) >= 0) {
        const block = buf.slice(0, i); buf = buf.slice(i + 2);
        const ev = /event: (\w+)/.exec(block)?.[1];
        const data = JSON.parse(/data: (.*)/s.exec(block)?.[1] || "{}");
        if (ev === "session") sid = data.sessionId;
        else if (ev === "step") onStep?.(data);
        else if (ev === "result") result = data;
        else if (ev === "error") throw new Error(data.error);
      }
    }
    return { ...result, sessionId: sid };
  },
};

export const fileToDataUrl = (file) => new Promise((resolve, reject) => {
  const fr = new FileReader(); fr.onload = () => resolve(fr.result); fr.onerror = reject; fr.readAsDataURL(file);
});
